excels.excel:

EXPORT WITH SHEET="部门季度绩效考核汇总表", HEADER=true,
    MAPPING={"a":"部门","b":"考核负责人","c":"目标完成分","d":"工作质量分","e":"团队协作分","f":"综合得分","g":"考核等级"},
    FORMAT={"c":"0.00","d":"0.00","e":"0.00","f":"0.00"},
    FORMULAS={
        F2:'C2*0.5+D2*0.3+E2*0.2',F3:'C3*0.5+D3*0.3+E3*0.2',
        F4:'C4*0.5+D4*0.3+E4*0.2',F5:'C5*0.5+D5*0.3+E5*0.2',
        F6:'C6*0.5+D6*0.3+E6*0.2',
        C7:'AVERAGE(C2:C6)',D7:'AVERAGE(D2:D6)',E7:'AVERAGE(E2:E6)',F7:'AVERAGE(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
